}

export interface InteractiveSong {
  id: string;
  title: string;
  author: string;
  bpm: number;
  difficulty: 'facile' | 'medio' | 'difficile' | 'easy' | 'medium' | 'hard';
  hand?: 'right' | 'left'; // Preferenza o rilevamento mano (destra o sinistra)
