import React from 'react';
import { ViewMode, StudioTheme } from '../types';
import { Piano, BookOpen, Layers, Volume2, VolumeX, Home, Music, Users, ShieldCheck, Key, User, Disc, Timer, Palette } from 'lucide-react';
import { getThemeClasses, STUDIO_THEMES } from '../utils/themeHelper';
import { midiEngine } from '../utils/midiEngine';
import { APP_VERSION } from '../utils/versionInfo';

interface NavbarProps {
  currentView: ViewMode | 'home';
  onSelectView: (view: ViewMode | 'home') => void;
  volume: number;
  onVolumeChange: (vol: number) => void;
  isAudioActive: boolean;
  onInitAudio: () => void;
  username: string;
  onOpenIdentityModal: () => void;
  onOpenMetronome?: () => void;
  studioTheme: StudioTheme;
  onThemeChange: (theme: StudioTheme) => void;
  onOpenScalesModal: () => void;
  onOpenVersionModal?: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({
  currentView,
  onSelectView,
  volume,
  onVolumeChange,
  isAudioActive,
  onInitAudio,
  username,
  onOpenIdentityModal,
  onOpenMetronome,
  studioTheme,
  onThemeChange,
  onOpenScalesModal,
  onOpenVersionModal,
}) => {
  const theme = getThemeClasses(studioTheme);

  return (
    <header className={`relative w-full ${theme.navBg} backdrop-blur-md border-b select-none z-30 shrink-0`}>
      {/* 5-Line Musical Pentagramma Micro-Stave Border Accent */}
      <div className="absolute bottom-0 left-0 right-0 h-[2px] opacity-25 flex flex-col justify-between pointer-events-none">
        <div className="w-full h-[0.5px] bg-gradient-to-r from-transparent via-amber-400 to-transparent" />
        <div className="w-full h-[0.5px] bg-gradient-to-r from-transparent via-amber-500 to-transparent" />
      </div>

      <div className="max-w-7xl mx-auto px-2 sm:px-4 h-12 sm:h-13 flex items-center justify-between gap-1.5 sm:gap-4">
        {/* BRAND LOGO: Luxury Musical Emblem */}
        <div
          onClick={() => onSelectView('home')}
          className="flex items-center gap-1.5 sm:gap-2.5 cursor-pointer group shrink-0"
          title="Return to Home"
        >
          {/* Vinyl Disc with Golden Treble Clef */}
          <div className="relative w-7 h-7 sm:w-8 sm:h-8 rounded-full bg-gradient-to-tr from-amber-600 via-amber-400 to-yellow-300 p-0.5 shadow-md shadow-amber-500/20 group-hover:scale-105 transition-transform">
            <div className="w-full h-full rounded-full bg-slate-950 flex items-center justify-center border border-amber-500/40">
              <span className="text-amber-400 text-xs sm:text-sm font-serif leading-none select-none">
                𝄞
              </span>
            </div>
          </div>

          {/* Wordmark with Mini Visualizer */}
          <div className="flex items-baseline gap-1 sm:gap-1.5">
            <span className="text-sm sm:text-base font-black tracking-tight text-transparent bg-clip-text bg-gradient-to-r from-amber-200 via-amber-400 to-yellow-400">
              VIRTUKEYS
            </span>
            <span className="hidden xs:inline-block text-[9px] uppercase tracking-widest font-extrabold text-amber-400/90 bg-amber-500/10 px-1 py-0.2 rounded border border-amber-500/20">
              STUDIO
            </span>
            {onOpenVersionModal && (
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onOpenVersionModal();
                }}
                className="hidden md:inline-flex items-center gap-1 text-[9px] font-mono font-bold text-slate-500 hover:text-amber-300 bg-slate-900/80 hover:bg-slate-800 border border-slate-800 px-1.5 py-0.2 rounded transition-colors cursor-pointer ml-1"
                title="Versione Studio: v1.0.157 - Clicca per dettagli aggiornamento"
              >
                <span className="w-1 h-1 rounded-full bg-emerald-400" />
                <span>v{APP_VERSION}</span>
              </button>
            )}
          </div>

          {/* Dancing Mini Equalizer Bars */}
          <div className="hidden sm:flex items-end gap-0.5 h-3.5 pl-1 opacity-70">
            <span className="w-0.5 h-2 bg-amber-400 rounded-full animate-pulse" />
            <span className="w-0.5 h-3.5 bg-amber-300 rounded-full animate-pulse [animation-delay:150ms]" />
            <span className="w-0.5 h-1.5 bg-yellow-400 rounded-full animate-pulse [animation-delay:300ms]" />
            <span className="w-0.5 h-3 bg-amber-500 rounded-full animate-pulse [animation-delay:75ms]" />
          </div>
        </div>

        {/* ULTRA-COMPACT SEGMENTED MUSICAL CONTROLLER (Zero Scroll, Fits Everything) */}
        <nav className="flex items-center bg-slate-900/90 p-0.5 sm:p-1 rounded-xl border border-slate-800 shadow-inner overflow-hidden">
          {/* HOME */}
          <button
            onClick={() => onSelectView('home')}
            className={`px-1.5 sm:px-2.5 py-1 rounded-lg flex items-center gap-1 text-[11px] sm:text-xs font-bold transition-all ${
              currentView === 'home'
                ? 'bg-gradient-to-r from-amber-500 to-amber-400 text-slate-950 font-black shadow-sm'
                : 'text-slate-400 hover:text-white hover:bg-slate-800/80'
            }`}
            title="Main Screen"
          >
            <Home className="w-3.5 h-3.5 shrink-0" />
            <span className="hidden md:inline">Home</span>
          </button>

          {/* PIANO */}
          <button
            onClick={() => {
              onInitAudio();
              onSelectView('piano');
            }}
            className={`px-2 sm:px-3 py-1 rounded-lg flex items-center gap-1 sm:gap-1.5 text-[11px] sm:text-xs font-bold transition-all ${
              currentView === 'piano'
                ? 'bg-gradient-to-r from-amber-500 to-amber-400 text-slate-950 font-black shadow-sm'
                : 'text-slate-400 hover:text-white hover:bg-slate-800/80'
            }`}
            title="Interactive 88-key grand piano with falling notes waterfall"
          >
            <Piano className="w-3.5 h-3.5 shrink-0" />
            <span>Piano</span>
          </button>

          {/* SHEET MUSIC COMPOSER */}
          <button
            onClick={() => {
              onInitAudio();
              onSelectView('sheet');
            }}
            className={`px-2 sm:px-3 py-1 rounded-lg flex items-center gap-1 sm:gap-1.5 text-[11px] sm:text-xs font-bold transition-all ${
              currentView === 'sheet'
                ? 'bg-gradient-to-r from-amber-500 to-amber-400 text-slate-950 font-black shadow-sm'
                : 'text-slate-400 hover:text-white hover:bg-slate-800/80'
            }`}
            title="Sheet Music Composer with MIDI & JSON export"
          >
            <BookOpen className="w-3.5 h-3.5 shrink-0" />
            <span>Sheet Music</span>
            <span className="hidden lg:inline text-[9px] bg-slate-950/40 px-1 rounded text-amber-200">
              MIDI
            </span>
          </button>

          {/* JAM BAND */}
          <button
            onClick={() => {
              onInitAudio();
              onSelectView('jam');
            }}
            className={`px-2 sm:px-2.5 py-1 rounded-lg flex items-center gap-1 sm:gap-1.5 text-[11px] sm:text-xs font-bold transition-all ${
              currentView === 'jam'
                ? 'bg-gradient-to-r from-amber-500 to-amber-400 text-slate-950 font-black shadow-sm'
                : 'text-slate-400 hover:text-white hover:bg-slate-800/80'
            }`}
            title="Jam Band with drums, bass & rhythm sections"
          >
            <Layers className="w-3.5 h-3.5 shrink-0" />
            <span>Jam</span>
          </button>

          {/* SOCIAL & CHALLENGES */}
          <button
            onClick={() => {
              onInitAudio();
              onSelectView('social');
            }}
            className={`px-2 sm:px-2.5 py-1 rounded-lg flex items-center gap-1 sm:gap-1.5 text-[11px] sm:text-xs font-bold transition-all ${
              currentView === 'social'
                ? 'bg-gradient-to-r from-amber-500 to-amber-400 text-slate-950 font-black shadow-sm'
                : 'text-slate-400 hover:text-white hover:bg-slate-800/80'
            }`}
            title="Masterclass, Battles, Quiz & Virtual Piano Bar"
          >
            <Users className="w-3.5 h-3.5 shrink-0" />
            <span>Social</span>
          </button>

          {/* RECORDINGS MANAGER */}
          <button
            onClick={() => {
              onInitAudio();
              onSelectView('recordings');
            }}
            className={`px-2 sm:px-2.5 py-1 rounded-lg flex items-center gap-1 sm:gap-1.5 text-[11px] sm:text-xs font-bold transition-all ${
              currentView === 'recordings'
                ? 'bg-gradient-to-r from-amber-500 to-amber-400 text-slate-950 font-black shadow-sm'
                : 'text-slate-400 hover:text-white hover:bg-slate-800/80'
            }`}
            title="Recordings Manager: Listen, rename, and delete saved tracks"
          >
            <Disc className="w-3.5 h-3.5 shrink-0 text-amber-400" />
            <span>Recordings</span>
          </button>
        </nav>

        {/* SCALES PRACTICE, METRONOME & THEME SELECTOR */}
        <div className="flex items-center gap-1.5 sm:gap-2 shrink-0">
          {/* Scales & Warmup Hub Button */}
          <button
            onClick={() => {
              onInitAudio();
              onOpenScalesModal();
            }}
            className="flex items-center gap-1 px-2 py-1 bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/30 text-amber-300 rounded-xl text-[10px] sm:text-xs font-black transition-all shadow-sm active:scale-95 cursor-pointer"
            title="Scales & Warmup Gym (Hanon, 12 Keys, Arpeggios)"
          >
            <Layers className="w-3.5 h-3.5 text-amber-400 shrink-0" />
            <span>Scales</span>
          </button>

          {/* Theme Selector Pills (Responsive) */}
          <div className="flex items-center bg-slate-900 border border-slate-800 p-0.5 rounded-xl gap-0.5">
            {STUDIO_THEMES.map((th) => (
              <button
                key={th.id}
                onClick={() => onThemeChange(th.id)}
                className={`px-1.5 py-0.5 rounded-lg text-[10px] font-bold transition-all cursor-pointer whitespace-nowrap ${
                  studioTheme === th.id
                    ? 'bg-amber-500 text-slate-950 shadow font-black'
                    : 'text-slate-400 hover:text-white'
                }`}
                title={`${th.name} — ${th.desc}`}
              >
                <span className="lg:hidden">{th.icon}</span>
                <span className="hidden lg:inline">{th.icon} {th.shortName}</span>
              </button>
            ))}
          </div>

          {/* Quick Metronome Button */}
          {onOpenMetronome && (
            <button
              onClick={() => {
                onInitAudio();
                onOpenMetronome();
              }}
              className="flex items-center gap-1 px-2 py-1 bg-slate-900 hover:bg-slate-800 border border-amber-500/30 text-amber-300 rounded-xl text-[10px] sm:text-xs font-black transition-all shadow-sm active:scale-95 cursor-pointer"
              title="Open Metronome & Practice Tools"
            >
              <Timer className="w-3.5 h-3.5 text-amber-400 shrink-0" />
              <span className="hidden xs:inline">Metronome</span>
            </button>
          )}

          <button
            onClick={onOpenIdentityModal}
            className="flex items-center gap-1 px-2 py-1 bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/30 text-amber-300 rounded-xl text-[10px] sm:text-xs font-black transition-all shadow-sm active:scale-95 cursor-pointer"
            title="Protected account on this device. Click to view Transfer Code or switch device."
          >
            <ShieldCheck className="w-3.5 h-3.5 text-amber-400 shrink-0" />
            <span className="truncate max-w-[80px] sm:max-w-[110px]">{username || 'Pianist'}</span>
            <span className="text-[9px] bg-amber-400 text-slate-950 font-black px-1 rounded uppercase">🔒</span>
          </button>

          {/* Quick Volume Slider */}
          <div className="hidden xs:flex items-center gap-1 sm:gap-1.5 bg-slate-900/90 px-2 py-1 rounded-xl border border-slate-800">
            {volume <= -25 ? (
              <VolumeX className="w-3 h-3 text-red-400 shrink-0" />
            ) : (
              <Volume2 className="w-3 h-3 text-amber-400 shrink-0" />
            )}
            <input
              type="range"
              min="-30"
              max="6"
              step="1"
              value={volume}
              onChange={(e) => onVolumeChange(Number(e.target.value))}
              className="w-12 sm:w-16 h-1 accent-amber-500 bg-slate-700 rounded cursor-pointer"
              title="Master Volume"
            />
          </div>

          {/* Hi-Fi Audio Status Indicator */}
          {!isAudioActive ? (
            <button
              onClick={onInitAudio}
              className="px-2 sm:px-2.5 py-1 text-[10px] sm:text-xs font-black text-slate-950 bg-amber-400 hover:bg-amber-300 rounded-lg transition-colors whitespace-nowrap shadow-sm shadow-amber-400/20 active:scale-95 animate-pulse flex items-center gap-1"
              title="Click to enable audio"
            >
              <Music className="w-3 h-3" />
              <span>Enable Audio</span>
            </button>
          ) : (
            <div
              className="flex items-center gap-1 px-2 py-1 text-[9px] sm:text-[10px] font-bold text-emerald-400 bg-emerald-950/50 border border-emerald-500/30 rounded-lg whitespace-nowrap"
              title="Hi-Fi Audio active and ready"
            >
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-ping" />
              <span className="hidden sm:inline">HI-FI</span>
              <span>44.1k</span>
            </div>
          )}

          {/* USB/Bluetooth MIDI Status Badge */}
          {(() => {
            const [midiStatus, setMidiStatus] = React.useState(() => midiEngine.getStatus());
            React.useEffect(() => {
              const unsubscribe = midiEngine.subscribe((st) => setMidiStatus(st));
              return unsubscribe;
            }, []);
            return (
              <div
                onClick={() => midiEngine.init()}
                className={`hidden md:flex items-center gap-1 px-2 py-1 text-[9px] sm:text-[10px] font-bold rounded-lg whitespace-nowrap border cursor-pointer transition-all ${
                  midiStatus.isConnected
                    ? 'text-emerald-400 bg-emerald-950/50 border-emerald-500/30 hover:bg-emerald-900/60'
                    : 'text-amber-300 bg-amber-950/40 border-amber-500/30 hover:bg-amber-900/50'
                }`}
                title={midiStatus.isConnected ? `MIDI Keyboard Connected: ${midiStatus.deviceNames.join(', ')}` : 'No MIDI keyboard detected. Connect via USB-OTG or Bluetooth MIDI and click to activate.'}
              >
                <span className={`w-1.5 h-1.5 rounded-full ${midiStatus.isConnected ? 'bg-emerald-400 animate-ping' : 'bg-amber-400'}`} />
                <span>🎹 MIDI: {midiStatus.isConnected ? (midiStatus.deviceNames[0] || 'Connected') : 'Disconnected'}</span>
              </div>
            );
          })()}
        </div>
      </div>
    </header>
  );
};

src/components/HomeView.tsx:
import React, { useState } from 'react';
import { ViewMode } from '../types';
import {
  Piano,
  BookOpen,
  Radio,
  ArrowRight,
  Music,
  Disc3,
  Volume2,
  Sparkles,
  Flame,
  Award,
  Users,
  Layers,
  ShieldCheck,
} from 'lucide-react';
import { audioEngine } from '../utils/audioEngine';
import { loadGamificationState } from '../utils/gamification';
import { APP_VERSION } from '../utils/versionInfo';
import { TutorialModal } from './TutorialModal';
import { isNativePlatform } from '../utils/networkHelper';

interface HomeViewProps {
  onSelectView: (view: ViewMode) => void;
  onInitAudio: () => void;
  onOpenScalesModal?: () => void;
  onOpenVersionModal?: () => void;
  onOpenPlayAssetsModal?: () => void;
}

export const HomeView: React.FC<HomeViewProps> = ({
  onSelectView,
  onInitAudio,
  onOpenScalesModal,
  onOpenVersionModal,
  onOpenPlayAssetsModal,
}) => {
  const [isPlayingWelcome, setIsPlayingWelcome] = useState<boolean>(false);
  const [isTutorialOpen, setIsTutorialOpen] = useState<boolean>(false);
  const [gamification] = useState(() => loadGamificationState());
  const [, setActiveTabPreview] = useState<string | null>(null);

  // Play a lush, inspiring acoustic grand piano arpeggio on title tap
  const playWelcomeChord = async () => {
    onInitAudio();
    if (isPlayingWelcome) return;
    setIsPlayingWelcome(true);

    const notes = ['C3', 'G3', 'C4', 'E4', 'G4', 'B4', 'D5'];
    for (let i = 0; i < notes.length; i++) {
      audioEngine.playNote(notes[i], '2n', 'piano');
      await new Promise((r) => setTimeout(r, 85));
    }

    setTimeout(() => {
      setIsPlayingWelcome(false);
    }, 1600);
  };

  const handleOpenMode = (view: ViewMode) => {
    onInitAudio();
    onSelectView(view);
  };

  // Shared card dimension and structure classes for pixel-perfect uniformity across all 8 cards (2 rows of 4)
  const cardBaseClass =
    'group relative w-[calc(50%-0.45rem)] sm:w-[calc(25%-0.6rem)] p-3 sm:p-3.5 rounded-2xl cursor-pointer transition-all duration-300 hover:shadow-xl hover:-translate-y-0.5 flex flex-col justify-between overflow-hidden min-h-[165px] sm:min-h-[178px] shrink-0';

  return (
    <div className="relative max-w-6xl mx-auto px-3 sm:px-5 pt-2 pb-2.5 sm:pt-2.5 sm:pb-3 flex flex-col justify-between min-h-[calc(100vh-4rem)] select-none">
      {/* Background Decorative Ambient Lighting */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden -z-10">
        <div className="absolute top-1/4 left-1/2 -translate-x-1/2 w-96 h-96 bg-amber-500/10 rounded-full blur-3xl" />
        <div className="absolute bottom-10 left-10 w-72 h-72 bg-indigo-500/10 rounded-full blur-3xl" />
        <div className="absolute top-10 right-10 w-72 h-72 bg-emerald-500/10 rounded-full blur-3xl" />
      </div>

      {/* COMPACT ARTISTIC TITLE LOGO - Positioned with equal distance to top bar and to boxes */}
      <div className="flex items-center justify-center gap-2 sm:gap-3 mt-0.5 mb-2 sm:mt-1 sm:mb-2.5 shrink-0">
        <div className="h-[1px] flex-1 max-w-[80px] sm:max-w-[140px] bg-gradient-to-r from-transparent via-amber-500/30 to-amber-400/60 hidden sm:block" />

        <div
          onClick={playWelcomeChord}
          className="group relative flex items-center gap-2.5 sm:gap-3 px-3.5 sm:px-4 py-1 sm:py-1.5 rounded-full bg-slate-900/90 hover:bg-slate-800/95 border border-amber-500/40 hover:border-amber-400 shadow-md shadow-amber-500/10 cursor-pointer transition-all hover:scale-[1.02] active:scale-95"
          title="VirtuKeys Studio - Click to play test chord"
        >
          {/* Artistic Luxury Clef Crest */}
          <div className="relative w-6 h-6 sm:w-7 sm:h-7 rounded-full bg-gradient-to-tr from-amber-600 via-amber-400 to-yellow-300 p-[1.5px] shadow-sm shadow-amber-500/40 shrink-0">
            <div className="w-full h-full rounded-full bg-slate-950 flex items-center justify-center">
              <span className="text-amber-400 text-xs sm:text-sm font-serif leading-none select-none">
                𝄞
              </span>
            </div>
          </div>

          {/* Stylized Designed Brand Name */}
          <div className="flex items-baseline gap-1.5 sm:gap-2">
            <span className="text-base sm:text-lg md:text-xl font-black tracking-wider text-transparent bg-clip-text bg-gradient-to-r from-amber-200 via-amber-400 to-yellow-500 drop-shadow-[0_0_15px_rgba(245,158,11,0.35)]">
              VIRTUKEYS
            </span>
            <span className="h-3 w-px bg-amber-500/40" />
            <span className="text-[10px] sm:text-xs font-semibold tracking-[0.2em] text-slate-300 uppercase font-sans">
              STUDIO
            </span>
          </div>

          {/* Interactive Audio Chime Icon Indicator */}
          <span className="text-[10px] text-amber-400/80 group-hover:text-amber-300 flex items-center gap-1 pl-1 border-l border-slate-700/60 ml-0.5">
            <Music className={`w-3 h-3 ${isPlayingWelcome ? 'animate-bounce text-amber-300' : 'text-amber-400/70'}`} />
            <span className="hidden md:inline text-[9px] font-mono font-medium text-amber-300/80">
              {isPlayingWelcome ? 'Playing...' : 'Test Chord'}
            </span>
          </span>
        </div>

        <div className="h-[1px] flex-1 max-w-[80px] sm:max-w-[140px] bg-gradient-to-l from-transparent via-amber-500/30 to-amber-400/60 hidden sm:block" />
      </div>

      {/* 2-ROW UNIFORM CARDS: All 7 cards have the EXACT same width, height, and proportions */}
      <div className="flex flex-wrap justify-center gap-2.5 sm:gap-3 max-w-5xl mx-auto w-full my-auto flex-1 items-center">
        {/* CARD 1: PIANO */}
        <div
          onClick={() => handleOpenMode('piano')}
          onMouseEnter={() => {
            setActiveTabPreview('piano');
            audioEngine.playNote('C4', '8n', 'piano');
          }}
          className={`${cardBaseClass} bg-gradient-to-b from-slate-900/95 via-slate-900/90 to-slate-950 border border-amber-500/30 hover:border-amber-400 hover:shadow-amber-500/20`}
        >
          <div className="flex items-center justify-between">
            <span className="text-[9px] font-black uppercase tracking-wider text-amber-400 bg-amber-500/10 border border-amber-500/30 px-2 py-0.5 rounded-full">
              88 KEYS
            </span>
            <div className="w-1.5 h-1.5 rounded-full bg-amber-400 group-hover:animate-ping" />
          </div>

          <div className="my-2 space-y-1.5 flex-1">
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 sm:w-9 sm:h-9 rounded-xl bg-gradient-to-tr from-amber-600 to-yellow-400 flex items-center justify-center text-slate-950 shadow-md shadow-amber-500/30 group-hover:scale-105 transition-transform shrink-0">
                <Piano className="w-4 h-4 stroke-[2.2]" />
              </div>
              <div className="min-w-0">
                <h3 className="text-sm sm:text-base font-black text-white group-hover:text-amber-300 transition-colors leading-tight truncate">
                  Piano
                </h3>
                <span className="text-[10px] text-amber-400/90 font-medium truncate block">88 Keys & Waterfall</span>
              </div>
            </div>

            <p className="text-slate-400 text-[11px] leading-snug line-clamp-2 h-[2.5rem]">
              88-key piano keyboard, falling notes waterfall, and built-in recorder.
            </p>
          </div>

          <div className="pt-2 border-t border-slate-800/80 flex items-center justify-between text-amber-400 font-bold text-[11px] group-hover:text-amber-300">
            <span>Play Now</span>
            <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
          </div>
        </div>

        {/* CARD 2: SHEET MUSIC COMPOSER */}
        <div
          onClick={() => handleOpenMode('sheet')}
          onMouseEnter={() => {
            setActiveTabPreview('sheet');
            audioEngine.playNote('E4', '8n', 'piano');
          }}
          className={`${cardBaseClass} bg-gradient-to-b from-slate-900/95 via-slate-900/90 to-slate-950 border border-indigo-500/30 hover:border-indigo-400 hover:shadow-indigo-500/20`}
        >
          <div className="flex items-center justify-between">
            <span className="text-[9px] font-black uppercase tracking-wider text-indigo-400 bg-indigo-500/10 border border-indigo-500/30 px-2 py-0.5 rounded-full">
              SHEET MUSIC
            </span>
            <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 group-hover:animate-ping" />
          </div>

          <div className="my-2 space-y-1.5 flex-1">
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 sm:w-9 sm:h-9 rounded-xl bg-gradient-to-tr from-indigo-600 to-indigo-400 flex items-center justify-center text-white shadow-md shadow-indigo-500/30 group-hover:scale-105 transition-transform shrink-0">
                <BookOpen className="w-4 h-4 stroke-[2.2]" />
              </div>
              <div className="min-w-0">
                <h3 className="text-sm sm:text-base font-black text-white group-hover:text-indigo-300 transition-colors leading-tight truncate">
                  Composer
                </h3>
                <span className="text-[10px] text-indigo-400/90 font-medium truncate block">Score & Notation</span>
              </div>
            </div>

            <p className="text-slate-400 text-[11px] leading-snug line-clamp-2 h-[2.5rem]">
              Compose sheet music note-by-note and export directly to MIDI.
            </p>
          </div>

          <div className="pt-2 border-t border-slate-800/80 flex items-center justify-between text-indigo-400 font-bold text-[11px] group-hover:text-indigo-300">
            <span>Compose</span>
            <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
          </div>
        </div>

        {/* CARD 3: JAM BAND STUDIO */}
        <div
          onClick={() => handleOpenMode('jam')}
          onMouseEnter={() => {
            setActiveTabPreview('jam');
            audioEngine.playNote('G3', '8n', 'piano');
          }}
          className={`${cardBaseClass} bg-gradient-to-b from-slate-900/95 via-slate-900/90 to-slate-950 border border-emerald-500/30 hover:border-emerald-400 hover:shadow-emerald-500/20`}
        >
          <div className="flex items-center justify-between">
            <span className="text-[9px] font-black uppercase tracking-wider text-emerald-400 bg-emerald-500/10 border border-emerald-500/30 px-2 py-0.5 rounded-full">
              LIVE BAND
            </span>
            <div className="w-1.5 h-1.5 rounded-full bg-emerald-400 group-hover:animate-ping" />
          </div>

          <div className="my-2 space-y-1.5 flex-1">
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 sm:w-9 sm:h-9 rounded-xl bg-gradient-to-tr from-emerald-600 to-teal-400 flex items-center justify-center text-slate-950 shadow-md shadow-emerald-500/30 group-hover:scale-105 transition-transform shrink-0">
                <Radio className="w-4 h-4 stroke-[2.2]" />
              </div>
              <div className="min-w-0">
                <h3 className="text-sm sm:text-base font-black text-white group-hover:text-emerald-300 transition-colors leading-tight truncate">
                  Jam Band
                </h3>
                <span className="text-[10px] text-emerald-400/90 font-medium truncate block">Live Drums & Bass</span>
              </div>
            </div>

            <p className="text-slate-400 text-[11px] leading-snug line-clamp-2 h-[2.5rem]">
              Jam with auto-accompaniment on live drum rhythms and bass lines.
            </p>
          </div>

          <div className="pt-2 border-t border-slate-800/80 flex items-center justify-between text-emerald-400 font-bold text-[11px] group-hover:text-emerald-300">
            <span>Start Jam</span>
            <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
          </div>
        </div>

        {/* CARD 4: SCALE GYM */}
        <div
          onClick={() => {
            onInitAudio();
            if (onOpenScalesModal) onOpenScalesModal();
          }}
          onMouseEnter={() => {
